#!/usr/bin/env python3
"""
patch_42_ext2.py

Filesystem/partition integration, step 2 (per Part 6 / Part 18.10's
roadmap continued): a read-only ext2 driver, built fresh against
hal::registry::block_read() (the BlockDevice HAL), with on-disk field
layouts cross-checked against the OSDev wiki and Linux's fs/ext2/ext2.h.

Does four things:
  1. Creates kernel/src/fs/ext2.rs (new file - aborts if it already exists).
  2. Adds `pub mod ext2;` to kernel/src/fs/mod.rs.
  3. Adds a new `ext2test` kshell command to main.rs, inserted right after
     the existing gpttest arm (patch_41).
  4. Updates the help command's printed list to include ext2test.

Requires patch_41 already applied (targets its exact post-patch text).
Run from ~/nexus-os/kernel/src.
"""
import os
import sys

FS_DIR = "fs"
EXT2_FILE = os.path.join(FS_DIR, "ext2.rs")
MOD_FILE = os.path.join(FS_DIR, "mod.rs")
MAIN_FILE = "main.rs"

EXT2_RS_CONTENT = '//! ext2 filesystem driver — read-only, first slice (patch_42).\n//!\n//! Written fresh against this project\'s own hal::registry::block_read()\n//! (the BlockDevice HAL abstraction, not drivers::nvme directly), with\n//! on-disk field layouts cross-checked against the OSDev wiki\'s ext2 page\n//! and Linux\'s fs/ext2/ext2.h — the same "external reference as cross-\n//! check, not copy source" role Redox\'s nvmed played for the NVMe driver\n//! (see Part 4 bug #31\'s closing note in this project\'s own log).\n//!\n//! Scope of this first patch, deliberately narrow (same principle that\n//! capped the NVMe I/O path at <=4KB/single-namespace, and left GPT CRC32\n//! validation for a follow-up):\n//!   - Read-only. No write/create/delete support at all.\n//!   - Direct blocks only (inode.i_block[0..12]) — no singly/doubly/triply\n//!     indirect block support. This caps any single file OR directory at\n//!     12 * block_size bytes (e.g. 48KB at the common 4096-byte block\n//!     size). Anything larger returns FileTooLargeForDirectBlocksOnly.\n//!   - Root-directory lookups only (lookup_in_root) — no multi-level path\n//!     resolution ("/a/b/c" is out of scope; only a bare filename directly\n//!     under the partition\'s root directory).\n//!   - No symlink handling.\n//!   - Only the first 128 bytes of each inode are read, which covers every\n//!     field this module uses regardless of the on-disk s_inode_size\n//!     (128 is the spec-guaranteed minimum) — extended inode fields beyond\n//!     that (e.g. nanosecond timestamps on 256-byte inodes) are untouched.\n//!   - i_size is read as the low 32 bits only (i_size_lo) — files >= 4GiB\n//!     are out of scope, consistent with everything else here.\n//!   - No feature-flag validation (s_feature_incompat / s_feature_ro_compat)\n//!     — this module assumes a standard mke2fs-created ext2 filesystem with\n//!     the usual defaults, not an ext3/ext4 volume or one using unusual\n//!     ext2 feature bits.\n\nextern crate alloc;\nuse alloc::{string::String, vec, vec::Vec};\n\nuse crate::hal;\n\npub const ROOT_INODE: u32 = 2;\nconst EXT2_MAGIC: u16 = 0xEF53;\nconst S_IFDIR: u16 = 0x4000;\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum Ext2Error {\n    NoBlockDevice,\n    ReadError,\n    BadMagic,\n    NotADirectory,\n    IsADirectory,\n    NotFound,\n    InvalidInode,\n    FileTooLargeForDirectBlocksOnly,\n}\n\nfn u16_from_le(b: &[u8]) -> u16 {\n    u16::from_le_bytes([b[0], b[1]])\n}\n\nfn u32_from_le(b: &[u8]) -> u32 {\n    let mut arr = [0u8; 4];\n    arr.copy_from_slice(&b[0..4]);\n    u32::from_le_bytes(arr)\n}\n\n/// Reads `len` bytes starting at `byte_offset` within the partition\n/// beginning at `partition_start_lba`, translating the (possibly\n/// sector-unaligned) byte range into whole-sector hal::registry::block_read()\n/// calls, batched at up to 4096 bytes per call (the same cap\n/// io_read_blocks/block_read enforce). This is the one place in this\n/// module that talks to the BlockDevice HAL — every other function in\n/// this file goes through this.\nfn read_bytes_at(partition_start_lba: u64, byte_offset: u64, len: usize) -> Result<Vec<u8>, Ext2Error> {\n    if len == 0 {\n        return Ok(Vec::new());\n    }\n    let sector_size = hal::registry::block_size() as u64;\n    if sector_size == 0 {\n        return Err(Ext2Error::NoBlockDevice);\n    }\n\n    let abs_byte_offset = partition_start_lba * sector_size + byte_offset;\n    let start_lba = abs_byte_offset / sector_size;\n    let start_offset_in_sector = (abs_byte_offset % sector_size) as usize;\n    let end_byte_exclusive = abs_byte_offset + len as u64;\n    let last_lba = (end_byte_exclusive - 1) / sector_size;\n    let num_lbas = (last_lba - start_lba + 1) as usize;\n\n    let max_lbas_per_call = (4096 / sector_size as usize).max(1);\n    let mut raw = Vec::with_capacity(num_lbas * sector_size as usize);\n    let mut lba = start_lba;\n    let mut remaining_lbas = num_lbas;\n    while remaining_lbas > 0 {\n        let this_call_lbas = remaining_lbas.min(max_lbas_per_call);\n        let call_bytes = this_call_lbas * sector_size as usize;\n        let mut buf = vec![0u8; call_bytes];\n        hal::registry::block_read(lba, &mut buf).map_err(|_| Ext2Error::ReadError)?;\n        raw.extend_from_slice(&buf);\n        lba += this_call_lbas as u64;\n        remaining_lbas -= this_call_lbas;\n    }\n\n    let start = start_offset_in_sector;\n    let end = start + len;\n    if end > raw.len() {\n        return Err(Ext2Error::ReadError);\n    }\n    Ok(raw[start..end].to_vec())\n}\n\n#[derive(Debug, Clone, Copy)]\npub struct Ext2Superblock {\n    pub inodes_count: u32,\n    pub blocks_count: u32,\n    pub log_block_size: u32,\n    pub blocks_per_group: u32,\n    pub inodes_per_group: u32,\n    pub magic: u16,\n    pub rev_level: u32,\n    pub inode_size: u16,\n}\n\nimpl Ext2Superblock {\n    pub fn block_size(&self) -> u32 {\n        1024u32 << self.log_block_size\n    }\n}\n\nfn parse_superblock(raw: &[u8]) -> Result<Ext2Superblock, Ext2Error> {\n    let magic = u16_from_le(&raw[56..58]);\n    if magic != EXT2_MAGIC {\n        return Err(Ext2Error::BadMagic);\n    }\n    let rev_level = u32_from_le(&raw[76..80]);\n    let inode_size = if rev_level == 0 {\n        128\n    } else {\n        u16_from_le(&raw[88..90])\n    };\n    Ok(Ext2Superblock {\n        inodes_count: u32_from_le(&raw[0..4]),\n        blocks_count: u32_from_le(&raw[4..8]),\n        log_block_size: u32_from_le(&raw[24..28]),\n        blocks_per_group: u32_from_le(&raw[32..36]),\n        inodes_per_group: u32_from_le(&raw[40..44]),\n        magic,\n        rev_level,\n        inode_size,\n    })\n}\n\n#[derive(Debug, Clone)]\npub struct Ext2Fs {\n    pub partition_start_lba: u64,\n    pub sb: Ext2Superblock,\n}\n\n/// Mounts (read-only, in the sense of "parses enough to read") the ext2\n/// filesystem believed to start at `partition_start_lba` — the superblock\n/// always lives at byte offset 1024 from the start of whatever it\'s on,\n/// regardless of block size, so this doesn\'t need the partition\'s block\n/// size known in advance.\npub fn mount(partition_start_lba: u64) -> Result<Ext2Fs, Ext2Error> {\n    let raw = read_bytes_at(partition_start_lba, 1024, 1024)?;\n    let sb = parse_superblock(&raw)?;\n    Ok(Ext2Fs { partition_start_lba, sb })\n}\n\nstruct BlockGroupDescriptor {\n    inode_table: u32,\n}\n\nfn read_block_group_descriptor(fs: &Ext2Fs, group: u32) -> Result<BlockGroupDescriptor, Ext2Error> {\n    let block_size = fs.sb.block_size() as u64;\n    // The block group descriptor table starts immediately after the block\n    // containing the superblock: block 2 when block_size == 1024 (since\n    // the superblock then occupies block 1 on its own), block 1 otherwise\n    // (block 0 holds both the boot area and the superblock together).\n    let bgdt_block: u64 = if block_size == 1024 { 2 } else { 1 };\n    let bgd_byte_offset = bgdt_block * block_size + (group as u64 * 32);\n    let raw = read_bytes_at(fs.partition_start_lba, bgd_byte_offset, 32)?;\n    Ok(BlockGroupDescriptor {\n        inode_table: u32_from_le(&raw[8..12]),\n    })\n}\n\n#[derive(Debug, Clone, Copy)]\npub struct Inode {\n    pub i_mode: u16,\n    pub i_uid: u16,\n    pub i_gid: u16,\n    pub i_size: u32,\n    pub i_links_count: u16,\n    pub i_block: [u32; 15],\n}\n\nimpl Inode {\n    pub fn is_directory(&self) -> bool {\n        (self.i_mode & 0xF000) == S_IFDIR\n    }\n}\n\npub fn read_inode(fs: &Ext2Fs, inode_num: u32) -> Result<Inode, Ext2Error> {\n    if inode_num == 0 {\n        return Err(Ext2Error::InvalidInode);\n    }\n    let group = (inode_num - 1) / fs.sb.inodes_per_group;\n    let index_in_group = (inode_num - 1) % fs.sb.inodes_per_group;\n\n    let bgd = read_block_group_descriptor(fs, group)?;\n    let block_size = fs.sb.block_size() as u64;\n    let byte_offset = (bgd.inode_table as u64 * block_size) + (index_in_group as u64 * fs.sb.inode_size as u64);\n\n    // Only the first 128 bytes are read - every field this module uses\n    // lives within that range regardless of the on-disk inode size (128\n    // is the spec-guaranteed minimum).\n    let raw = read_bytes_at(fs.partition_start_lba, byte_offset, 128)?;\n\n    let mut i_block = [0u32; 15];\n    for (i, slot) in i_block.iter_mut().enumerate() {\n        let off = 40 + i * 4;\n        *slot = u32_from_le(&raw[off..off + 4]);\n    }\n\n    Ok(Inode {\n        i_mode: u16_from_le(&raw[0..2]),\n        i_uid: u16_from_le(&raw[2..4]),\n        i_size: u32_from_le(&raw[4..8]),\n        i_gid: u16_from_le(&raw[24..26]),\n        i_links_count: u16_from_le(&raw[26..28]),\n        i_block,\n    })\n}\n\n#[derive(Debug, Clone)]\npub struct DirEntry {\n    pub inode: u32,\n    pub name: String,\n    pub file_type: u8,\n}\n\n/// Lists the entries of a directory inode. Direct blocks only (see module\n/// doc) — a directory whose entries spill past i_block[0..12] will simply\n/// have its later entries silently unavailable, not an error, since\n/// legitimate small directories (like every one this first slice is\n/// tested against) never approach that size.\npub fn read_dir_entries(fs: &Ext2Fs, dir_inode_num: u32) -> Result<Vec<DirEntry>, Ext2Error> {\n    let inode = read_inode(fs, dir_inode_num)?;\n    if !inode.is_directory() {\n        return Err(Ext2Error::NotADirectory);\n    }\n\n    let block_size = fs.sb.block_size() as u64;\n    let mut entries = Vec::new();\n\n    for &block_num in inode.i_block[0..12].iter() {\n        if block_num == 0 {\n            continue; // unused direct-block slot\n        }\n        let raw = read_bytes_at(fs.partition_start_lba, block_num as u64 * block_size, block_size as usize)?;\n\n        let mut off = 0usize;\n        while off + 8 <= raw.len() {\n            let ino = u32_from_le(&raw[off..off + 4]);\n            let rec_len = u16_from_le(&raw[off + 4..off + 6]) as usize;\n            let name_len = raw[off + 6] as usize;\n            let file_type = raw[off + 7];\n\n            if rec_len == 0 {\n                break; // corrupt entry; avoid an infinite loop\n            }\n            if ino != 0 && off + 8 + name_len <= raw.len() {\n                if let Ok(name) = core::str::from_utf8(&raw[off + 8..off + 8 + name_len]) {\n                    entries.push(DirEntry {\n                        inode: ino,\n                        name: String::from(name),\n                        file_type,\n                    });\n                }\n            }\n            off += rec_len;\n        }\n    }\n\n    Ok(entries)\n}\n\n/// Looks up a bare filename directly under the partition\'s root\n/// directory. No multi-level path resolution — see module doc.\npub fn lookup_in_root(fs: &Ext2Fs, name: &str) -> Result<u32, Ext2Error> {\n    let entries = read_dir_entries(fs, ROOT_INODE)?;\n    entries\n        .into_iter()\n        .find(|e| e.name == name)\n        .map(|e| e.inode)\n        .ok_or(Ext2Error::NotFound)\n}\n\n/// Reads a regular file\'s full contents. Direct blocks only — files\n/// larger than 12 * block_size return FileTooLargeForDirectBlocksOnly\n/// rather than silently truncating.\npub fn read_file(fs: &Ext2Fs, inode_num: u32) -> Result<Vec<u8>, Ext2Error> {\n    let inode = read_inode(fs, inode_num)?;\n    if inode.is_directory() {\n        return Err(Ext2Error::IsADirectory);\n    }\n\n    let block_size = fs.sb.block_size() as u64;\n    let size = inode.i_size as usize;\n    if size as u64 > 12 * block_size {\n        return Err(Ext2Error::FileTooLargeForDirectBlocksOnly);\n    }\n\n    let mut data = Vec::with_capacity(size);\n    let mut remaining = size;\n    for &block_num in inode.i_block[0..12].iter() {\n        if remaining == 0 {\n            break;\n        }\n        let this_len = remaining.min(block_size as usize);\n        if block_num == 0 {\n            // Sparse block - real ext2 files can have holes; read as zeros.\n            data.extend(core::iter::repeat(0u8).take(this_len));\n        } else {\n            let raw = read_bytes_at(fs.partition_start_lba, block_num as u64 * block_size, this_len)?;\n            data.extend_from_slice(&raw);\n        }\n        remaining -= this_len;\n    }\n\n    Ok(data)\n}\n'

MOD_OLD = 'pub mod procfs;\npub mod tmpfs;\npub mod vfs;\npub mod elf;\npub mod initrd;\npub mod partition;'

MOD_NEW = 'pub mod procfs;\npub mod tmpfs;\npub mod vfs;\npub mod elf;\npub mod initrd;\npub mod partition;\npub mod ext2;'

HELP_OLD = '        crate::kprint!("Commands: help meminfo version reboot ticks uptime syscalls scrubtest teardowntest multitest audittest heaptest isotest isofault wxtest guardtest captest permtest ipctest spawn restest conctest preempttest drawtest ownertest haltest pcitest mmiotest nvmeinittest identifytest nvmeiotest blockdevtest gpttest'

HELP_NEW = '        crate::kprint!("Commands: help meminfo version reboot ticks uptime syscalls scrubtest teardowntest multitest audittest heaptest isotest isofault wxtest guardtest captest permtest ipctest spawn restest conctest preempttest drawtest ownertest haltest pcitest mmiotest nvmeinittest identifytest nvmeiotest blockdevtest gpttest ext2test'

DISPATCH_OLD = '            Err(e) => {\n                crate::kprintln!("[gpttest] FAIL - read_gpt() returned {:?}", e);\n                crate::kprintln!("[gpttest] (this is expected/PASS-equivalent if the attached disk has no GPT yet, e.g. a fresh qemu-img raw file - BadSignature means \\"no GPT found\\", not \\"parser broken\\")");\n            }\n        }\n    } else if !b.is_empty() {'

DISPATCH_NEW = '            Err(e) => {\n                crate::kprintln!("[gpttest] FAIL - read_gpt() returned {:?}", e);\n                crate::kprintln!("[gpttest] (this is expected/PASS-equivalent if the attached disk has no GPT yet, e.g. a fresh qemu-img raw file - BadSignature means \\"no GPT found\\", not \\"parser broken\\")");\n            }\n        }\n    } else if b == b"ext2test" {\n        crate::kprintln!("--- ext2 filesystem test (superblock, root dir, file read - via BlockDevice HAL) ---");\n        match fs::partition::read_gpt() {\n            Ok(entries) if !entries.is_empty() => {\n                let part = &entries[0];\n                crate::kprintln!("[ext2test] using partition 0: LBA {}..={}", part.first_lba, part.last_lba);\n                match fs::ext2::mount(part.first_lba) {\n                    Ok(fsobj) => {\n                        crate::kprintln!(\n                            "[ext2test] superblock OK - magic={:#06x} block_size={} inodes_count={} blocks_count={} inode_size={}",\n                            fsobj.sb.magic, fsobj.sb.block_size(), fsobj.sb.inodes_count, fsobj.sb.blocks_count, fsobj.sb.inode_size\n                        );\n                        match fs::ext2::read_dir_entries(&fsobj, fs::ext2::ROOT_INODE) {\n                            Ok(dirents) => {\n                                crate::kprintln!("[ext2test] root directory: {} entries", dirents.len());\n                                for e in &dirents {\n                                    crate::kprintln!("[ext2test]   inode={} name=\\"{}\\" type={}", e.inode, e.name, e.file_type);\n                                }\n                                match fs::ext2::lookup_in_root(&fsobj, "hello.txt") {\n                                    Ok(inode_num) => match fs::ext2::read_file(&fsobj, inode_num) {\n                                        Ok(data) => {\n                                            let expected: &[u8] = b"Noxisa ext2 read test";\n                                            crate::kprintln!("[ext2test] read hello.txt: {} bytes", data.len());\n                                            if data == expected {\n                                                crate::kprintln!("[ext2test] memcmp PASS - contents match exactly");\n                                                crate::kprintln!("[ext2test] PASS - superblock, directory listing, and file read all verified");\n                                            } else {\n                                                crate::kprintln!("[ext2test] FAIL - contents do not match expected test string");\n                                            }\n                                        }\n                                        Err(e) => crate::kprintln!("[ext2test] FAIL - read_file returned {:?}", e),\n                                    },\n                                    Err(e) => crate::kprintln!("[ext2test] FAIL - lookup_in_root(\\"hello.txt\\") returned {:?} (did you create it on the host before booting?)", e),\n                                }\n                            }\n                            Err(e) => crate::kprintln!("[ext2test] FAIL - read_dir_entries returned {:?}", e),\n                        }\n                    }\n                    Err(e) => crate::kprintln!("[ext2test] FAIL - mount returned {:?} (is the partition actually formatted as ext2?)", e),\n                }\n            }\n            Ok(_) => crate::kprintln!("[ext2test] FAIL - GPT parsed but has no used partitions"),\n            Err(e) => crate::kprintln!("[ext2test] FAIL - read_gpt returned {:?} (run gpttest first to confirm GPT is present)", e),\n        }\n    } else if !b.is_empty() {'


def patch_create_file(path, content):
    if os.path.exists(path):
        print(f"ABORT: {path} already exists. Nothing written.")
        return False
    with open(path, "w") as f:
        f.write(content)
    print(f"[patch_42] OK - created {path}")
    return True


def patch_replace(path, old, new, label):
    try:
        with open(path, "r") as f:
            content = f.read()
    except FileNotFoundError:
        print(f"ABORT: {path} not found in current directory")
        return False

    count = content.count(old)
    print(f"[patch_42] {label} match count in {path}: {count}")
    if count != 1:
        print(f"ABORT: expected exactly 1 match for {label}. Nothing written to {path}.")
        return False

    with open(path, "w") as f:
        f.write(content.replace(old, new))
    print(f"[patch_42] OK - patched {path} ({label})")
    return True


def main():
    if not os.path.isdir(FS_DIR):
        print(f"ABORT: {FS_DIR}/ not found - run this from kernel/src")
        sys.exit(1)

    ok = True
    ok &= patch_create_file(EXT2_FILE, EXT2_RS_CONTENT)
    ok &= patch_replace(MOD_FILE, MOD_OLD, MOD_NEW, "fs/mod.rs pub mod list")
    ok &= patch_replace(MAIN_FILE, HELP_OLD, HELP_NEW, "help string")
    ok &= patch_replace(MAIN_FILE, DISPATCH_OLD, DISPATCH_NEW, "ext2test dispatch arm")

    if not ok:
        print("[patch_42] ABORTED - one or more steps failed. Review output above.")
        sys.exit(1)

    print("[patch_42] All steps applied successfully.")


if __name__ == "__main__":
    main()
